assert hashlib.sha256(source).hexdigest()=='aa58fb19ba0229a213cdc319bc204ccd393389c366c2818f388f1d00b06a89df'
exec(compile(source,'hpc_ingest_response_bytes.py','exec'),{'__name__':'__main__'})
